export interface LinkHistoryPoint {
  /** ISO-8601 timestamp of the run, as written by the checker. */
  date: string;
  /** Unique external URLs cited across tracked Markdown files. */
  urls: number;
  /** Citations the host served: verdict PASS (HTTP 200). */
  served: number;
  /** Citations it could not check: BLOCKED + SERVER_ERROR + UNREACHABLE. */
  notChecked: number;
  /** Citations that answered but failed the check. */
  failed: number;
  blocked: number;
  unreachable: number;
  serverError: number;
  /** Every verdict name the checker emitted, so a new verdict shows up without a code change. */
  verdicts: Record<string, number>;
}

